import os
os.environ['OPENBLAS_NUM_THREADS']='1'
import numpy as np
from itertools import combinations,product
rng=np.random.default_rng(98)
for m in [1,2,3]:
    As=[];Bs=[];Ap=[];Bp=[]
    j=2*m;d=3*m
    for cs in combinations(range(1,j),m-1):
      two={0,*cs}
      for js in product(range(3),repeat=j):
        a=[];b=[];ap=[];bp=[]
        for c in range(j):
          sole=3*c+js[c];pair=[3*c+t for t in range(3) if t!=js[c]]
          if c in two:a.extend(pair);b.append(sole);bp.append(pair)
          else:a.append(sole);b.extend(pair);ap.append(pair)
        As.append(a);Bs.append(b);Ap.append(ap);Bp.append(bp)
    As=np.array(As);Bs=np.array(Bs);Ap=np.array(Ap);Bp=np.array(Bp)
    def count(P):
      na=np.linalg.solve(P[As],np.ones((len(As),d,1)))[...,0]
      va=np.einsum('gkhi,gi->gkh',P[Ap],na)-1
      inds=np.flatnonzero(np.all(va[:,:,0]*va[:,:,1]<0,axis=1))
      nb=np.linalg.solve(P[Bs[inds]],np.ones((len(inds),d,1)))[...,0]
      vb=np.einsum('gkhi,gi->gkh',P[Bp[inds]],nb)-1
      return sum(np.all(vb[:,:,0]*vb[:,:,1]<0,axis=1))
    print('m',m,'counts',[count(rng.normal(size=(3*j,d))) for _ in range(20)],flush=True)
